import{_ as e,o as d,c as o,a2 as r}from"./chunks/framework.iWwp2X7T.js";const _=JSON.parse('{"title":"问题排查","description":"Mobile Inspector development documentation · 问题排查","frontmatter":{"title":"问题排查","description":"Mobile Inspector development documentation · 问题排查"},"headers":[],"relativePath":"zh/troubleshooting/index.md","filePath":"zh/troubleshooting/index.md"}'),a={name:"zh/troubleshooting/index.md"};function n(i,t,c,s,h,l){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="问题排查" tabindex="-1">问题排查 <a class="header-anchor" href="#问题排查" aria-label="Permalink to &quot;问题排查&quot;">​</a></h1><p>先读取 <code>--version</code> 与 <code>doctor --json</code>，记录所选版本、home、命令与固定错误码。支持信息中不能包含凭据、配对 JSON 或私有正文。</p><table tabindex="0"><thead><tr><th>现象</th><th>检查与下一步</th></tr></thead><tbody><tr><td>私有仓库克隆拒绝</td><td>确认仓库授权，公开文档不授予权限</td></tr><tr><td>Owner 冲突或旧状态</td><td>核对所有权，选择独立自有 home，不能杀任意 PID</td></tr><tr><td>手机二维码不可用</td><td>选择可路由 LAN 地址，回环只供本地</td></tr><tr><td>摄像头拒绝</td><td>使用手工配对，新扫描动作才申请摄像头</td></tr><tr><td>已配置但无事件</td><td>独立开启记录，核对真实 Transport 与目标</td></tr><tr><td>浏览器、微信或 Harmony TLS 失败</td><td>提供系统信任 HTTPS，检查域名及来源策略</td></tr><tr><td>轨迹有缺口</td><td>检查预算、序号和完整性，不能声称完整采集</td></tr><tr><td>MCP 游标陈旧</td><td>主动按同项目重新列出，不复用其他代次</td></tr><tr><td>Codex 诊断拒绝</td><td><code>UNSUPPORTED_SANDBOX</code> 是当前门禁，不能绕过</td></tr></tbody></table><h2 id="区分原因" tabindex="-1">区分原因 <a class="header-anchor" href="#区分原因" aria-label="Permalink to &quot;区分原因&quot;">​</a></h2><p>503 是 HTTP 观察，不证明客户端代码有错；取消可能符合预期；来源映射缺失表示证据不完整。归因前检查<a href="./../reference/incidents">事件语义</a>。</p><p>USB 先检查物理信任、线缆和 Xcode 发现，再配对。导出即便不含正文也需复核日志。换号或环境变化时清除并断开，旧回调应失效。设备行为不确定时明确未验证，不能用浏览器或单元测试替代实际到达。</p>',6)])])}const m=e(a,[["render",n]]);export{_ as __pageData,m as default};
